import { createContext } from "react";
import { ContentTypes } from "constants/contentstack";
import { IContentstackHeader } from "interface/content/header";
import { IContentstackPage } from "interface/content/page";
import { IDirectoryData } from "interface/directory";
import { IOnboarding } from "interface/onboarding";

export interface IContentstackContext {
  header?: [IContentstackHeader];
  footer?: [any];
  onboarding?: [IOnboarding];
  page?: [IContentstackPage];
  pagesBaseURLs?: {
    [key in ContentTypes]?: string;
  };
  directories?: IDirectoryData;
  languageAlternativePageSlug?: string[];
  /**
   * Re-fetched draft entry data pushed by the Contentstack Live Preview
   * subscription in _app.tsx. Page-level providers merge it over the
   * server-side props so useContent consumers re-render with draft content.
   *
   * Holds only the subset of context fields that were re-fetched (e.g.
   * `{ page: [entry] }`), never a full nested context — hence Partial.
   */
  livePreviewContent?: Partial<IContentstackContext> | null;
}

export const ContentstackContext = createContext<IContentstackContext>({});

import { GetStaticPaths, GetStaticProps, NextPage } from "next";
import { useContext } from "react";
import { serverSideTranslations } from "next-i18next/serverSideTranslations";
import { Layout } from "components/layout/Layout";
import { PageHead } from "components/pages/PageHead";
import { ContentstackContext, IContentstackContext } from "context/contentstackContext";
import { IContentstackHeader } from "interface/content/header";
import { IContentstackPage } from "interface/content/page";
import { IDirectoryData, IMappedByLocaleDirectories } from "interface/directory";
import { IOnboarding } from "interface/onboarding";
import { resolvePageComponent } from "services/pageComponentResolver";
import { pageService } from "services/pageService";
import { staticPathsResolver } from "services/staticPathsResolver";
import { readFromFs } from "utils/fsCache";
import { getLocaleByNextLocale, NextLocales } from "utils/locale";
import { readCachedPageDataFromFs } from "utils/pageDataCache";
import { refineClientData } from "utils/refineClientData";

interface IDynamicSlugParams {
  slug: string[];
}

interface IPageProps {
  content: {
    header: [IContentstackHeader];
    footer: [any];
    page: [IContentstackPage];
    directories: IDirectoryData;
    languageAlternativePageSlug?: string[];
    onboarding: [IOnboarding];
  };
  contentTypeUid: string;
}

const Page: NextPage<IPageProps> = (props) => {
  const { content, contentTypeUid } = props;
  const PageComponent = resolvePageComponent(contentTypeUid);
  const { livePreviewContent } = useContext(ContentstackContext);

  // In live preview, overlay the re-fetched draft entries onto the published content
  const mergedContent = (
    livePreviewContent ? { ...content, ...livePreviewContent } : content
  ) as IContentstackContext;

  return (
    <ContentstackContext.Provider value={mergedContent}>
      <PageHead page={mergedContent.page || content.page} contentTypeUid={contentTypeUid} />
      <Layout contentTypeUid={contentTypeUid}>
        {PageComponent ? <PageComponent {...mergedContent} /> : <h1>Page not implemented</h1>}
      </Layout>
    </ContentstackContext.Provider>
  );
};

export const getStaticPaths: GetStaticPaths = async () => {
  const { MAINTENANCE_MODE } = process.env;

  if (MAINTENANCE_MODE === "true") {
    return { paths: [], fallback: false };
  }

  return {
    paths: await staticPathsResolver.resolveStaticPaths(),
    fallback: false,
  };
};

export const getStaticProps: GetStaticProps = async (context) => {
  const { locale: nextLocale = "" } = context;
  const { slug = [] } = (context?.params as unknown as IDynamicSlugParams) || {};
  const {
    uid: pageUid,
    contentTypeUid,
    languageAlternativePageSlug = "",
  } = readCachedPageDataFromFs([nextLocale, ...slug]);

  const contentstackLocale = getLocaleByNextLocale(nextLocale);
  const directories = readFromFs<IMappedByLocaleDirectories>({ fileName: "directories" });
  const currentLocaleDirectories = directories?.[contentstackLocale] || {};

  const content = await pageService.getPageEntry({
    contentTypeUid,
    entryUid: pageUid,
    lang: contentstackLocale,
  });

  const pageSpecificData = await pageService.getPageSpecificData({
    contentTypeUid,
    entryUid: pageUid,
    lang: contentstackLocale,
    page: content.page,
  });

  const cachedPagesBaseURLs = readFromFs<{ [locale: string]: Record<string, string> }>({
    fileName: "pagesBaseURLs",
  });
  const pagesBaseURLs = cachedPagesBaseURLs?.[contentstackLocale];

  return {
    props: {
      content: refineClientData(
        {
          ...content,
          page: [content.page],
          pageSpecificData,
          directories: currentLocaleDirectories,
          languageAlternativePageSlug,
          pagesBaseURLs,
        },
        nextLocale as NextLocales,
      ),
      contentTypeUid,
      ...(await serverSideTranslations(nextLocale, ["common"])),
    },
  };
};

export default Page;

import * as Utils from "@contentstack/utils";
import contentstack from "contentstack";
import { HttpStatusCode } from "@metrolinx/cx-shared/build/src/constants/common";
import { HttpError } from "@metrolinx/cx-shared/build/src/utils/common/HttpError";
import { ContentstackDebugLevel } from "constants/contentstack";
import { IInteractiveMapsConstructionNotice } from "interface/constructionNotice";
import { IContentstackContentType } from "interface/content/contentType";
import { IContentstackPage } from "interface/content/page";
import { isTestEnv } from "utils/envs";
import { InteractiveMapsContentType } from "../constants/constructionNotice";
import {
  ICommonContentstackConfig,
  IContentstackGetEntry,
  IContentstackGetInteractiveMapsStackEntry,
  IContentstackGetSingleEntry,
  IContentstackGetSingletonEntry,
  ICreateEntryConfig,
  ICreateQueryConfig,
} from "../interface/contentstack";
import { isContentstackApiError } from "../utils/isContentstackApiError";
import logger from "./logger";

const {
  API_KEY = "",
  DELIVERY_TOKEN = "",
  INTERACTIVE_MAPS_STACK_API_KEY = "",
  INTERACTIVE_MAPS_STACK_DELIVERY_TOKEN = "",
  INTERACTIVE_MAPS_STACK_ENVIRONMENT = "",
  INTERACTIVE_MAPS_STACK_BRANCH = "",
  ENVIRONMENT = "",
  CONTENTSTACK_API_HOST = "",
  CONTENTSTACK_BRANCH = "",
  CONTENTSTACK_FETCH_TIMEOUT = "",
  CONTENTSTACK_DEBUG = "",
  CONTENTSTACK_DEBUG_LEVEL = "error",
  CONTENTSTACK_PREVIEW_TOKEN = "",
} = process?.env || {};

const filterDebugLevel = (item: string): item is ContentstackDebugLevel =>
  [ContentstackDebugLevel.INFO, ContentstackDebugLevel.ERROR].includes(
    item as ContentstackDebugLevel,
  );

const contentstackDebugLevel = CONTENTSTACK_DEBUG_LEVEL.split(",")
  .map((item) => item.trim())
  .filter(filterDebugLevel);

const QUERY_RESPONSE_LIMIT = 100;

if (!isTestEnv()) {
  if (!API_KEY) {
    logger.error("Contentstack API key not provided");
  }

  if (!DELIVERY_TOKEN) {
    logger.error("Contentstack delivery token not provided");
  }

  if (!ENVIRONMENT) {
    logger.error("Contentstack environment not provided");
  }

  if (!CONTENTSTACK_BRANCH) {
    logger.error("Contentstack branch not provided");
  }

  if (!API_KEY || !DELIVERY_TOKEN || !ENVIRONMENT || !CONTENTSTACK_BRANCH) {
    throw new Error("Missing required environment variables");
  }
}

export const options: contentstack.Config = {
  api_key: API_KEY,
  delivery_token: DELIVERY_TOKEN,
  environment: ENVIRONMENT,
  branch: CONTENTSTACK_BRANCH,
  live_preview: {
    enable: true,
    // The live-preview endpoint is served from the REST API host (same env used for Stack.setHost),
    // defaulting to the public Contentstack API host when the env var is not set.
    host: CONTENTSTACK_API_HOST || "api.contentstack.io",
    // NOTE: the installed contentstack SDK (v3.17.2) consumes `management_token` inside live_preview
    // (see Stack.live_preview type). `preview_token` is NOT a recognised key in this SDK version, so
    // the Contentstack Preview Token is supplied via `management_token` for the SDK to authenticate
    // draft/preview requests. Do not rename to `preview_token` — the SDK would ignore it.
    management_token: CONTENTSTACK_PREVIEW_TOKEN,
  },
  fetchOptions: {
    debug: CONTENTSTACK_DEBUG === "true",
    logHandler: (level, data) => {
      const logLevel = level as ContentstackDebugLevel;

      if (contentstackDebugLevel.includes(logLevel)) {
        console[logLevel]("Contentstack SDK:", level, data);
      }
    },
    // https://www.contentstack.com/docs/developers/apis/content-delivery-api#errors
    retryCondition: (error) => [408, 429, 504].includes(error.status),
    ...(CONTENTSTACK_FETCH_TIMEOUT ? { timeout: Number(CONTENTSTACK_FETCH_TIMEOUT) } : {}),
  },
};

export const Stack = contentstack.Stack(options);

if (CONTENTSTACK_API_HOST) {
  Stack.setHost(CONTENTSTACK_API_HOST);
}

const renderOption = {
  span: (node: { children: any }, next: (arg0: any) => any) => next(node.children),
};

export const excludedFields = [
  "created_at",
  "created_by",
  "updated_at",
  "updated_by",
  "publish_details.user",
];

class ContentstackFactory {
  private stack: contentstack.Stack;

  constructor({ stack }: { stack: contentstack.Stack }) {
    this.stack = stack;
  }

  private setCommonConfig({
    query,
    ...config
  }: ICommonContentstackConfig & {
    query: contentstack.Query | contentstack.Entry;
  }) {
    const { referenceFieldPath, cachePolicy, only, except } = config;

    if (referenceFieldPath) {
      query.includeReference(referenceFieldPath);
    }

    if (cachePolicy) {
      query.setCachePolicy(cachePolicy);
    }

    if (!Array.isArray(except) && !Array.isArray(only)) {
      query.except(excludedFields);
    }

    if (only) {
      if (Array.isArray(only)) {
        query.only(only);
      } else {
        Object.entries(only).forEach(([key, values]) => query.only(key, values as string[]));
      }
    }

    if (except) {
      if (Array.isArray(except)) {
        query.except(except);
      } else {
        Object.entries(except).forEach(([key, values]) => query.except(key, values as string[]));
      }
    }
  }

  createContentTypeQuery({
    contentTypeUid,
    lang,
    where,
    count,
    skip,
    limit,
    ...commonConfig
  }: ICreateQueryConfig) {
    const query = this.stack.ContentType(contentTypeUid).Query().language(lang).toJSON();

    if (count) {
      query.includeCount();
    }

    if (skip) {
      query.skip(skip);
    }

    if (limit) {
      query.limit(limit);
    }

    this.setCommonConfig({ query, ...commonConfig });

    if (where) {
      Object.entries(where).forEach(([key, value]) => query.where(key, value));
    }

    return query;
  }

  createContentTypeEntryQuery({
    contentTypeUid,
    lang,
    entryUid,
    ...commonConfig
  }: ICreateEntryConfig) {
    const query = this.stack.ContentType(contentTypeUid).Entry(entryUid).language(lang).toJSON();

    this.setCommonConfig({ query, ...commonConfig });

    return query;
  }
}

export const getEntry = async <T>({
  contentTypeUid,
  referenceFieldPath,
  jsonRtePath,
  lang,
  cachePolicy,
}: IContentstackGetEntry): Promise<T> => {
  const result: any = [];

  const factory = new ContentstackFactory({ stack: Stack });

  const _query = factory.createContentTypeQuery({
    contentTypeUid,
    referenceFieldPath,
    lang,
    cachePolicy,
    except: excludedFields,
    count: true,
    skip: 0,
    limit: QUERY_RESPONSE_LIMIT,
  });

  try {
    const [response, count] = await _query.find();
    result.push(...response);

    while (result.length < count) {
      const _query = factory.createContentTypeQuery({
        contentTypeUid,
        lang,
        referenceFieldPath,
        except: excludedFields,
        count: true,
        skip: result.length,
        limit: QUERY_RESPONSE_LIMIT,
      });

      const [response]: any = await _query.find();

      result.push(...response);
    }

    if (jsonRtePath) {
      Utils.jsonToHTML({
        entry: result,
        paths: jsonRtePath,
        renderOption,
      });
    }

    return result;
  } catch (e: any) {
    logger.error(
      e.message,
      `Error retrieving entries of content type: ${contentTypeUid} for lang: ${lang}`,
    );
    throw e;
  }
};

export const getSingleEntry = async ({
  contentTypeUid,
  entryUid,
  lang,
  referenceFieldPath,
  jsonRtePath,
  only,
  except,
  cachePolicy,
}: IContentstackGetSingleEntry): Promise<IContentstackPage> => {
  const query = new ContentstackFactory({
    stack: Stack,
  }).createContentTypeEntryQuery({
    contentTypeUid,
    entryUid,
    referenceFieldPath,
    cachePolicy,
    only,
    except,
    lang,
  });

  try {
    const result = await query.fetch();

    if (jsonRtePath) {
      Utils.jsonToHTML({
        entry: result,
        paths: jsonRtePath,
        renderOption,
      });
    }

    return result;
  } catch (e: any) {
    logger.error(
      e.message,
      `Error retrieving single entry: ${entryUid} of content type: ${contentTypeUid} for lang: ${lang}`,
    );
    throw e;
  }
};

export const getPageContentTypes = async (): Promise<IContentstackContentType[]> => {
  const { content_types: contentTypes = [] } = await Stack.getContentTypes({
    query: { "options.is_page": true },
  });

  return contentTypes;
};

export const findSingletonEntry = async <
  T extends Pick<IContentstackPage, "uid"> = IContentstackPage,
>({
  contentTypeUid,
  lang,
  referenceFieldPath,
  cachePolicy,
  jsonRtePath,
  only,
  except,
  where,
}: IContentstackGetSingletonEntry): Promise<T | null> => {
  const query = new ContentstackFactory({
    stack: Stack,
  }).createContentTypeQuery({
    contentTypeUid,
    referenceFieldPath,
    cachePolicy,
    only,
    except,
    where,
    lang,
    limit: 1,
  });

  try {
    const [[result]]: T[][] = await query.find();

    if (!result) {
      return null;
    }

    if (jsonRtePath) {
      Utils.jsonToHTML({
        entry: result,
        paths: jsonRtePath,
        renderOption,
      });
    }

    return result;
  } catch (error) {
    logger.error(
      `Error retrieving entry of single content type: ${contentTypeUid} for lang: ${lang}`,
      error,
    );

    throw error;
  }
};

// TODO: Move to cx-shared
export const getSingletonEntry = async ({
  contentTypeUid,
  lang,
  referenceFieldPath,
  jsonRtePath,
  only,
  except,
  where,
  cachePolicy,
}: IContentstackGetSingletonEntry): Promise<IContentstackPage> => {
  const query = new ContentstackFactory({
    stack: Stack,
  }).createContentTypeQuery({
    contentTypeUid,
    referenceFieldPath,
    cachePolicy,
    only,
    except,
    where,
    lang,
  });

  try {
    const result = await query.findOne();

    if (jsonRtePath) {
      Utils.jsonToHTML({
        entry: result,
        paths: jsonRtePath,
        renderOption,
      });
    }

    return result;
  } catch (e: any) {
    logger.error(
      e.message,
      `Error retrieving entry of single content type: ${contentTypeUid} for lang: ${lang}`,
    );
    throw e;
  }
};

export async function getInteractiveMapsConstructionNoticeEntry({
  entryUid,
  lang,
}: IContentstackGetInteractiveMapsStackEntry): Promise<IInteractiveMapsConstructionNotice | null> {
  const interactiveMapsStackClient = contentstack.Stack({
    api_key: INTERACTIVE_MAPS_STACK_API_KEY,
    delivery_token: INTERACTIVE_MAPS_STACK_DELIVERY_TOKEN,
    environment: INTERACTIVE_MAPS_STACK_ENVIRONMENT || ENVIRONMENT,
    branch: INTERACTIVE_MAPS_STACK_BRANCH || CONTENTSTACK_BRANCH,
  });

  const contentType = InteractiveMapsContentType.CONSTRUCTION_NOTICE;
  const interactiveMapsExcludedFields = [...excludedFields, "publish_details"];

  try {
    const [entries]: IInteractiveMapsConstructionNotice[][] = await interactiveMapsStackClient
      .ContentType(contentType)
      .Query()
      .where("uid", entryUid)
      .language(lang)
      .except(interactiveMapsExcludedFields)
      .toJSON()
      .find();

    return entries[0] || null;
  } catch (error) {
    logger.error(
      error,
      `Failed to get Interactive Maps Construction Notice. ${entryUid} for lang: ${lang}`,
    );

    if (isContentstackApiError(error)) {
      throw new HttpError(error.error_message, {
        status: error.status,
        code: String(error.error_code),
        details: error.errors,
        cause: error,
      });
    }

    throw new HttpError("Failed to get Interactive Maps Construction Notice.", {
      status: HttpStatusCode.INTERNAL_SERVER_ERROR,
      cause: error,
    });
  }
}
